import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import './NotificationBell.css';

const API_URL = 'http://localhost:3003';
const WS_URL = 'ws://localhost:3003';

interface Notification {
    NotificationID: number;
    Message: string;
    IsRead: boolean;
    CreatedAt: string;
}

interface NotificationBellProps {
    role: 'hospital' | 'bloodBank';
}

const NotificationBell: React.FC<NotificationBellProps> = ({ role }) => {
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [isOpen, setIsOpen] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const dropdownRef = useRef<HTMLDivElement>(null);

    const fetchNotifications = async () => {
        try {
            const response = await axios.get<Notification[]>(`${API_URL}/notifications/${role}`);
            setNotifications(response.data);
        } catch (err) {
            setError('Failed to fetch notifications.');
            console.error(err);
        }
    };

    useEffect(() => {
        fetchNotifications();
        const ws = new WebSocket(WS_URL);
        ws.onmessage = (event) => {
            const message = JSON.parse(event.data);
            if (message.type === 'new_notification') {
                fetchNotifications();
            }
        };
        return () => ws.close();
    }, [role]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, []);

    const handleToggle = () => {
        setIsOpen(!isOpen);
    };

    const handleMarkAsRead = async (notificationId: number) => {
        try {
            await axios.put(`${API_URL}/notifications/${notificationId}`, { isRead: true });
            fetchNotifications();
        } catch (err) {
            setError('Failed to mark notification as read.');
            console.error(err);
        }
    };

    const handleClearAll = async () => {
        try {
            // This is a simplified example. In a real app, you'd likely have a dedicated endpoint.
            const unreadIds = notifications.filter(n => !n.IsRead).map(n => n.NotificationID);
            await Promise.all(
                unreadIds.map(id => axios.put(`${API_URL}/notifications/${id}`, { isRead: true }))
            );
            fetchNotifications();
        } catch (err) {
            setError('Failed to clear notifications.');
            console.error(err);
        }
    };

    const unreadCount = notifications.filter(n => !n.IsRead).length;

    return (
        <div className="notification-bell" ref={dropdownRef}>
            <button onClick={handleToggle} className="bell-icon">
                <i className="fas fa-bell"></i>
                {unreadCount > 0 && <span className="badge">{unreadCount}</span>}
            </button>
            {isOpen && (
                <div className="notifications-dropdown">
                    {error && <div className="error-message">{error}</div>}
                    <div className="notifications-header">
                        <h3>Notifications</h3>
                        {unreadCount > 0 && (
                            <button onClick={handleClearAll} className="clear-button">
                                Mark all as read
                            </button>
                        )}
                    </div>
                    {notifications.length === 0 ? (
                        <div className="no-notifications">No new notifications.</div>
                    ) : (
                        <ul className="notifications-list">
                            {notifications.map(n => (
                                <li
                                    key={n.NotificationID}
                                    className={n.IsRead ? 'read' : 'unread'}
                                    onClick={() => !n.IsRead && handleMarkAsRead(n.NotificationID)}
                                >
                                    <p>{n.Message}</p>
                                    <span>{new Date(n.CreatedAt).toLocaleString()}</span>
                                </li>
                            ))}
                        </ul>
                    )}
                </div>
            )}
        </div>
    );
};

export default NotificationBell;
